import * as arcoIcons from "@arco-design/web-react/icon";
import { convertToSnakeCase } from "./module";
import { JSONSchemaCustom } from "@/components/schema";
import { ModuleItem } from "@/components/CustomPage/interface";


export const getArcoIcon = (key: string) => {
    if(arcoIcons[key]) return arcoIcons[key];

    return () => `NotIcon: ${key}`;
}


export const getArcoIconName = (key: string) => {
    return `arcos_${convertToSnakeCase(key)}`;
}

const iconProps: JSONSchemaCustom = {
    type: "object",
    properties: {
        "style": { type: "object", format: "style" },
        "className": { type: "string", format: "class" },
        "spin": { type: "boolean", description: "是否旋转" },
    }
}

const arcoModules: any = {};

export const getArcoIconModule = (key: string) => {
    if(arcoModules[key]) return arcoModules[key];
    arcoModules[key] = {
        key: getArcoIconName(key),
        name: key,
        nickname: key,
        category: "General",
        source: "@arco-design/web-react/icon",
        display: "inline",
        props: iconProps,
        extraInfo: {}
    } as ModuleItem;
    return arcoModules[key];
}