import React, { useContext, useMemo } from "react";
import PageRouteContext from "./context";
import { Switch, Route, Redirect,  } from "react-router-dom";


interface PageRouteProps {
    defaultPath?: string;
}

const PageRoute = ({ defaultPath }: PageRouteProps) => {

    const context = useContext(PageRouteContext);


    const routeChildren = useMemo(() => {
        const routes = [];
        if(context){
            const { children = [] } = context.route;
            for (const route of children) {
                routes.push(
                    <Route
                        key={route.key}
                        exact={route.path == '*'? false : !route.isLayout}
                        path={route.path}
                        component={route.component}
                    />
                )
            }
        }
        return routes;
    },[context])


    const defaultRoute = useMemo(() => {
        if(defaultPath) return defaultPath;
        if(context){
            const { children = [] } = context.route;
            if(children.length) return children[0].path;
        }
        return ""
    },[defaultPath, context])


    if(context){

        return (
            <Switch>
                {routeChildren}
                {defaultRoute? (
                    <Route exact path="/">
                        <Redirect to={defaultRoute} />
                    </Route>
                ) : null}
            </Switch>
        )

    }

    return null;
    
}

export default PageRoute;