import { Form, FormProps, Collapse, CollapseProps, CollapseItemProps, Modal, ModalProps, Grid } from "@arco-design/web-react"
import React, { ReactNode, useEffect, useMemo, useState, useImperativeHandle, forwardRef } from "react";
import { useObserver } from "mobx-react-lite";
import { FormItem, JSONSchemaCustom } from "../interface";
import { schemaToFormItem, schemaToJSON } from "../utils";
import FormGenerate from "../FormGenerate";

export interface SchemaFormProps extends FormProps {
    ref?: any;
    schema: JSONSchemaCustom;
    /**
     * 需要过滤展示的schema 数据
     */
    filterKeys?: string[];
    // 编辑配置
    isEdit?: boolean;
    eidtProps?: {
        // 禁止编辑字段
        disbledKeys?: string[];
        // 编辑模式下隐藏字段
        hideKeys?: string[];
    }
    colSpan?: number;
    notCol?: boolean;
    // 标签宽度
    labelWidth?: string | number;
}


const SchemaForm = forwardRef(({
    form: parentForm,
    schema,
    colSpan,
    notCol,
    isEdit,
    eidtProps,
    filterKeys,
    labelWidth = `130px`,
    ...props
}: SchemaFormProps, ref: any) => {



    return useObserver(() => {
        const [form] = parentForm? [parentForm] : Form.useForm();

        const [key, initialValues] = useMemo(() => {
            return [Date.now(), schemaToJSON(schema)];
        }, [schema])
    
        useImperativeHandle(ref, () => {
            return form;
        },[])
    
        const formList = useMemo(() => {
            let list: FormItem[] = [];
            if(!Array.isArray(schema)){
                list = schemaToFormItem(schema)
            }
            if(isEdit && eidtProps){
                const { disbledKeys, hideKeys } = eidtProps;
                if(hideKeys){
                    list = list.filter((o) => !hideKeys.includes(o.field))
                }
                if(disbledKeys){
                    list = list.map((o) => {
                        if(disbledKeys.includes(o.field)){
                            o.fieldProps = {
                                ...o.fieldProps,
                                disabled: true
                            }
                        }
                        return o;
                    })
                }
            }

            if(filterKeys){
                const map =  new Map(list.map((o) => [o.field, o]));
                return filterKeys.map((k) => map.get(k)).filter((o) => Boolean(o));;
            }
            return list;
        },[schema, isEdit])
    
    
        console.log('props', props)
    
        return (
            <Form
                form={form}
                labelCol={{
                    style: { maxWidth: labelWidth }
                }}
                wrapperCol={{
                    style: { flex: '1 0 100px' }
                }}
                key={key}
                {...props}
                initialValues={{
                    ...initialValues,
                    ...props.initialValues,
                }}
            >
                <Grid.Row>
                    <FormGenerate
                        notCol={notCol}
                        colSpan={colSpan}
                        formList={formList}
                    />
                </Grid.Row>
            </Form>
        )
    })
})

export default SchemaForm;